  1→//! Cache storage implementation.
  2→
  3→use anyhow::{Context, Result};
  4→use sha2::{Digest, Sha256};
  5→use std::fs;
  6→use std::path::{Path, PathBuf};
  7→
  8→use super::entry::CacheEntry;
  9→
 10→/// Storage for cached templates.
 11→pub struct CacheStore {
 12→    /// Root directory for cache.
 13→    root: PathBuf,
 14→}
 15→
 16→impl CacheStore {
 17→    /// Create a new cache store.
 18→    pub fn new(root: impl Into<PathBuf>) -> Self {
 19→        Self { root: root.into() }
 20→    }
 21→
 22→    /// Get the cache root directory.
 23→    pub fn root(&self) -> &Path {
 24→        &self.root
 25→    }
 26→
 27→    /// Ensure the cache directory exists.
 28→    fn ensure_dir(&self) -> Result<()> {
 29→        fs::create_dir_all(&self.root)
 30→            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
 31→    }
 32→
 33→    /// Get the path for storing an entry's content.
 34→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 35→        let key = format!("{}:{}", source_id, template_name);
 36→        let hash = Sha256::digest(key.as_bytes());
 37→        let hash_str = hex::encode(&hash[..16]);
 38→        self.root.join(hash_str)
 39→    }
 40→
 41→    /// Get the metadata file path for an entry.
 42→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 43→        self.content_path(source_id, template_name)
 44→            .with_extension("meta.json")
 45→    }
 46→
 47→    /// Store content and return a cache entry.
 48→    pub fn store(
 49→        &self,
 50→        source_id: &str,
 51→        template_name: &str,
 52→        content: &str,
 53→        ttl_seconds: u64,
 54→    ) -> Result<CacheEntry> {
 55→        self.ensure_dir()?;
 56→
 57→        let content_path = self.content_path(source_id, template_name);
 58→        fs::write(&content_path, content)?;
 59→
 60→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 61→            .with_size(content.len() as u64);
 62→
 63→        self.save_metadata(&entry)?;
 64→
 65→        Ok(entry)
 66→    }
 67→
 68→    /// Load a cached entry's metadata.
 69→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 70→        let meta_path = self.metadata_path(source_id, template_name);
 71→
 72→        if !meta_path.exists() {
 73→            return Ok(None);
 74→        }
 75→
 76→        let json = fs::read_to_string(&meta_path)?;
 77→        let entry: CacheEntry = serde_json::from_str(&json)?;
 78→
 79→        Ok(Some(entry))
 80→    }
 81→
 82→    /// Read the cached content.
 83→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
 84→        fs::read_to_string(&entry.content_path).with_context(|| {
 85→            format!(
 86→                "Failed to read cached content from {:?}",
 87→                entry.content_path
 88→            )
 89→        })
 90→    }
 91→
 92→    /// Save entry metadata.
 93→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
 94→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
 95→        let json = serde_json::to_string_pretty(entry)?;
 96→        fs::write(&meta_path, json)?;
 97→        Ok(())
 98→    }
 99→
100→    /// Update an entry's metadata (e.g., after revalidation).
101→    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
102→        self.save_metadata(entry)
103→    }
104→
105→    /// Remove a cached entry.
106→    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
107→        let content_path = self.content_path(source_id, template_name);
108→        let meta_path = self.metadata_path(source_id, template_name);
109→
110→        let mut removed = false;
111→
112→        if content_path.exists() {
113→            fs::remove_file(&content_path)?;
114→            removed = true;
115→        }
116→
117→        if meta_path.exists() {
118→            fs::remove_file(&meta_path)?;
119→            removed = true;
120→        }

  1→//! Session storage.
  2→
  3→use std::fs;
  4→use std::path::PathBuf;
  5→
  6→use anyhow::{Context, Result};
  7→
  8→use super::{SessionId, SessionMetadata};
  9→
 10→/// A complete session record.
 11→#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
 12→pub struct Session {
 13→    /// Unique session identifier.
 14→    pub id: SessionId,
 15→    /// Session metadata.
 16→    pub metadata: SessionMetadata,
 17→}
 18→
 19→/// Storage for sessions.
 20→pub struct SessionStore {
 21→    path: PathBuf,
 22→}
 23→
 24→impl SessionStore {
 25→    /// Create a new session store.
 26→    pub fn new(path: impl Into<PathBuf>) -> Self {
 27→        Self { path: path.into() }
 28→    }
 29→
 30→    /// Ensure the store directory exists.
 31→    fn ensure_dir(&self) -> Result<()> {
 32→        fs::create_dir_all(&self.path)
 33→            .with_context(|| format!("Failed to create session store at {:?}", self.path))
 34→    }
 35→
 36→    /// Get the path for a session file.
 37→    fn session_path(&self, id: &SessionId) -> PathBuf {
 38→        self.path.join(format!("{}.json", id))
 39→    }
 40→
 41→    /// Save a session.
 42→    pub fn save(&self, session: &Session) -> Result<()> {
 43→        self.ensure_dir()?;
 44→        let path = self.session_path(&session.id);
 45→        let json = serde_json::to_string_pretty(session)?;
 46→        fs::write(&path, json).with_context(|| format!("Failed to write session to {:?}", path))
 47→    }
 48→
 49→    /// Load a session by ID.
 50→    pub fn load(&self, id: &SessionId) -> Result<Session> {
 51→        let path = self.session_path(id);
 52→        let json =
 53→            fs::read_to_string(&path).with_context(|| format!("Session not found: {:?}", path))?;
 54→        serde_json::from_str(&json).context("Failed to parse session")
 55→    }
 56→
 57→    /// Get the most recent session.
 58→    pub fn get_latest(&self) -> Result<Option<Session>> {
 59→        let sessions = self.list_recent(1)?;
 60→        Ok(sessions.into_iter().next())
 61→    }
 62→
 63→    /// List recent sessions.
 64→    pub fn list_recent(&self, limit: usize) -> Result<Vec<Session>> {
 65→        self.ensure_dir()?;
 66→
 67→        let mut sessions = Vec::new();
 68→        for entry in fs::read_dir(&self.path)? {
 69→            let entry = entry?;
 70→            let path = entry.path();
 71→            if path.extension().is_some_and(|e| e == "json") {
 72→                if let Ok(json) = fs::read_to_string(&path) {
 73→                    if let Ok(session) = serde_json::from_str::<Session>(&json) {
 74→                        sessions.push(session);
 75→                    }
 76→                }
 77→            }
 78→        }
 79→
 80→        // Sort by timestamp descending
 81→        sessions.sort_by(|a, b| b.id.timestamp().cmp(&a.id.timestamp()));
 82→        sessions.truncate(limit);
 83→
 84→        Ok(sessions)
 85→    }
 86→
 87→    /// Clean up old sessions (keep last N).
 88→    pub fn cleanup(&self, keep: usize) -> Result<usize> {
 89→        let sessions = self.list_recent(usize::MAX)?;
 90→        let mut removed = 0;
 91→
 92→        for session in sessions.into_iter().skip(keep) {
 93→            let path = self.session_path(&session.id);
 94→            if fs::remove_file(&path).is_ok() {
 95→                removed += 1;
 96→            }
 97→        }
 98→
 99→        Ok(removed)
100→    }
101→
102→    /// Get the store path.
103→    pub fn path(&self) -> &PathBuf {
104→        &self.path
105→    }
106→}
107→
