  1→//! Configuration inheritance resolution.
  2→//!
  3→//! This module handles the `extends:` configuration feature, which allows
  4→//! configs to inherit from remote base configurations.
  5→
  6→use std::collections::HashSet;
  7→use std::time::Duration;
  8→
  9→use anyhow::{anyhow, Result};
 10→
 11→use super::merger::deep_merge_with_leaves;
 12→use super::remote::RemoteFetcher;
 13→use super::schema::{BivvyConfig, ExtendsConfig};
 14→
 15→/// Resolves configuration inheritance chain.
 16→///
 17→/// # Example
 18→///
 19→/// ```no_run
 20→/// use bivvy::config::{BivvyConfig, ExtendsResolver};
 21→///
 22→/// let resolver = ExtendsResolver::new();
 23→///
 24→/// // Resolve a config that extends a remote base
 25→/// let config: BivvyConfig = serde_yaml::from_str(r#"
 26→/// extends:
 27→///   - url: https://example.com/base-config.yml
 28→/// app_name: MyApp
 29→/// "#).unwrap();
 30→///
 31→/// let resolved = resolver.resolve(&config).unwrap();
 32→/// ```
 33→pub struct ExtendsResolver {
 34→    fetcher: RemoteFetcher,
 35→    max_depth: usize,
 36→}
 37→
 38→impl ExtendsResolver {
 39→    /// Create a resolver with default settings.
 40→    pub fn new() -> Self {
 41→        Self {
 42→            fetcher: RemoteFetcher::new(Duration::from_secs(30)),
 43→            max_depth: 10,
 44→        }
 45→    }
 46→
 47→    /// Create a resolver with a custom fetcher.
 48→    pub fn with_fetcher(fetcher: RemoteFetcher) -> Self {
 49→        Self {
 50→            fetcher,
 51→            max_depth: 10,
 52→        }
 53→    }
 54→
 55→    /// Create a resolver with custom max depth.
 56→    pub fn with_max_depth(max_depth: usize) -> Self {
 57→        Self {
 58→            fetcher: RemoteFetcher::default(),
 59→            max_depth,
 60→        }
 61→    }
 62→
 63→    /// Resolve all extends references and merge configs.
 64→    pub fn resolve(&self, config: &BivvyConfig) -> Result<BivvyConfig> {
 65→        self.resolve_with_visited(config, &mut HashSet::new(), 0)
 66→    }
 67→
 68→    fn resolve_with_visited(
 69→        &self,
 70→        config: &BivvyConfig,
 71→        visited: &mut HashSet<String>,
 72→        depth: usize,
 73→    ) -> Result<BivvyConfig> {
 74→        if depth > self.max_depth {
 75→            return Err(anyhow!(
 76→                "Config extends depth exceeds maximum of {}",
 77→                self.max_depth
 78→            ));
 79→        }
 80→
 81→        // If no extends, return config as-is
 82→        let extends = match &config.extends {
 83→            Some(e) if !e.is_empty() => e,
 84→            _ => return Ok(config.clone()),
 85→        };
 86→
 87→        // Convert current config to Value for merging
 88→        let config_value = serde_yaml::to_value(config)?;
 89→
 90→        // Environment override blocks should replace entirely, not field-merge
 91→        let leaf_keys = std::collections::HashSet::from(["environments"]);
 92→
 93→        // Start with empty Value
 94→        let mut merged = serde_yaml::Value::Mapping(serde_yaml::Mapping::new());
 95→
 96→        // Process each base config in order
 97→        for ext in extends {
 98→            // Check for cycles
 99→            if visited.contains(&ext.url) {
100→                return Err(anyhow!("Circular extends detected: {}", ext.url));
101→            }
102→            visited.insert(ext.url.clone());
103→
104→            // Fetch and parse base config
105→            let content = self.fetcher.fetch(&ext.url)?;
106→            let base_config: BivvyConfig = serde_yaml::from_str(&content)?;
107→
108→            // Recursively resolve base's extends
109→            let resolved_base = self.resolve_with_visited(&base_config, visited, depth + 1)?;
110→
111→            // Convert to Value and merge
112→            let base_value = serde_yaml::to_value(&resolved_base)?;
113→            merged = deep_merge_with_leaves(&merged, &base_value, &leaf_keys);
114→        }
115→
116→        // Finally merge the current config on top
117→        let final_value = deep_merge_with_leaves(&merged, &config_value, &leaf_keys);
118→
119→        // Deserialize back to BivvyConfig
120→        let mut final_config: BivvyConfig = serde_yaml::from_value(final_value)?;

  1→//! HTTP template fetching.
  2→//!
  3→//! Provides an HTTP client for fetching templates from URLs with
  4→//! support for ETag-based conditional requests.
  5→
  6→use anyhow::{bail, Result};
  7→use reqwest::blocking::Client;
  8→use std::time::Duration;
  9→
 10→/// Default maximum response body size (10 MB).
 11→const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
 12→
 13→/// Fetches templates over HTTP/HTTPS.
 14→pub struct HttpFetcher {
 15→    client: Client,
 16→    timeout: Duration,
 17→    max_response_size: u64,
 18→}
 19→
 20→/// Response from fetching a template.
 21→#[derive(Debug)]
 22→pub struct FetchResponse {
 23→    /// The template content.
 24→    pub content: String,
 25→    /// ETag header if present.
 26→    pub etag: Option<String>,
 27→    /// Last-Modified header if present.
 28→    pub last_modified: Option<String>,
 29→}
 30→
 31→impl HttpFetcher {
 32→    /// Create a new HTTP fetcher with default 30-second timeout.
 33→    pub fn new() -> Self {
 34→        Self::with_timeout(Duration::from_secs(30))
 35→    }
 36→
 37→    /// Create a new HTTP fetcher with custom timeout.
 38→    pub fn with_timeout(timeout: Duration) -> Self {
 39→        Self {
 40→            client: Client::builder()
 41→                .user_agent("bivvy")
 42→                .timeout(timeout)
 43→                .build()
 44→                .expect("Failed to build HTTP client"),
 45→            timeout,
 46→            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
 47→        }
 48→    }
 49→
 50→    /// Create a new HTTP fetcher with custom timeout and max response size.
 51→    #[cfg(test)]
 52→    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
 53→        Self {
 54→            client: Client::builder()
 55→                .user_agent("bivvy")
 56→                .timeout(timeout)
 57→                .build()
 58→                .expect("Failed to build HTTP client"),
 59→            timeout,
 60→            max_response_size,
 61→        }
 62→    }
 63→
 64→    /// Get the configured timeout.
 65→    pub fn timeout(&self) -> Duration {
 66→        self.timeout
 67→    }
 68→
 69→    /// Fetch a template from a URL.
 70→    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
 71→        let response = self.client.get(url).send()?;
 72→
 73→        if !response.status().is_success() {
 74→            bail!("HTTP {} fetching {}", response.status(), url);
 75→        }
 76→
 77→        // Check Content-Length if available
 78→        if let Some(len) = response.content_length() {
 79→            if len > self.max_response_size {
 80→                bail!(
 81→                    "Response too large ({} bytes, max {} bytes) from {}",
 82→                    len,
 83→                    self.max_response_size,
 84→                    url
 85→                );
 86→            }
 87→        }
 88→
 89→        let etag = response
 90→            .headers()
 91→            .get("etag")
 92→            .and_then(|v| v.to_str().ok())
 93→            .map(String::from);
 94→
 95→        let last_modified = response
 96→            .headers()
 97→            .get("last-modified")
 98→            .and_then(|v| v.to_str().ok())
 99→            .map(String::from);
100→
101→        let content = response.text()?;
102→
103→        // Also check actual content size (in case Content-Length was missing/wrong)
104→        if content.len() as u64 > self.max_response_size {
105→            bail!(
106→                "Response too large ({} bytes, max {} bytes) from {}",
107→                content.len(),
108→                self.max_response_size,
109→                url
110→            );
111→        }
112→
113→        Ok(FetchResponse {
114→            content,
115→            etag,
116→            last_modified,
117→        })
118→    }
119→
120→    /// Fetch with conditional request (If-None-Match).

  1→//! Git template fetching.
  2→//!
  3→//! Provides functionality for cloning and updating git repositories
  4→//! to fetch templates, with support for specific refs and update detection.
  5→
  6→use anyhow::{bail, Result};
  7→use sha2::{Digest, Sha256};
  8→use std::path::{Path, PathBuf};
  9→
 10→/// Fetches templates from git repositories.
 11→pub struct GitFetcher {
 12→    /// Directory for cloned repositories.
 13→    clone_dir: PathBuf,
 14→}
 15→
 16→/// Information about a git fetch.
 17→#[derive(Debug)]
 18→pub struct GitFetchResult {
 19→    /// Path to the fetched content.
 20→    pub local_path: PathBuf,
 21→    /// Current commit SHA.
 22→    pub commit_sha: String,
 23→}
 24→
 25→impl GitFetcher {
 26→    /// Create a new git fetcher.
 27→    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
 28→        Self {
 29→            clone_dir: clone_dir.into(),
 30→        }
 31→    }
 32→
 33→    /// Get the clone directory.
 34→    pub fn clone_dir(&self) -> &PathBuf {
 35→        &self.clone_dir
 36→    }
 37→
 38→    /// Clone or update a repository.
 39→    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
 40→        let repo_path = self.repo_path(url);
 41→
 42→        if repo_path.exists() {
 43→            self.update_repo(&repo_path, git_ref)?;
 44→        } else {
 45→            self.clone_repo(url, &repo_path, git_ref)?;
 46→        }
 47→
 48→        let commit_sha = self.get_head_sha(&repo_path)?;
 49→
