  1→//! Environment probe for discovering version managers and tools.
  2→//!
  3→//! The biggest source of false negatives in requirement checking is version
  4→//! managers (nvm, rbenv, pyenv, mise) not being on PATH in non-interactive
  5→//! shells. Rust's `Command::new()` spawns a non-interactive, non-login shell
  6→//! where those initializations haven't run.
  7→//!
  8→//! The `EnvironmentProbe` runs before requirement checking to discover tools
  9→//! at well-known locations, producing an augmented PATH that subsequent checks
 10→//! use.
 11→//!
 12→//! # Example
 13→//!
 14→//! ```no_run
 15→//! use bivvy::requirements::probe::EnvironmentProbe;
 16→//!
 17→//! let probe = EnvironmentProbe::run();
 18→//! // Use augmented PATH for subsequent tool lookups
 19→//! for path in probe.augmented_path() {
 20→//!     println!("Additional PATH entry: {}", path.display());
 21→//! }
 22→//! for mgr in probe.inactive_managers() {
 23→//!     println!("{} found at {} but not active", mgr.name, mgr.install_path.display());
 24→//! }
 25→//! ```
 26→
 27→use std::path::{Path, PathBuf};
 28→
 29→/// A version manager detected as installed but not active in the current shell.
 30→#[derive(Debug, Clone)]
 31→pub struct InactiveManager {
 32→    /// Manager name (e.g., "nvm", "rbenv", "mise").
 33→    pub name: String,
 34→    /// Root install path (e.g., ~/.nvm, ~/.rbenv).
 35→    pub install_path: PathBuf,
 36→    /// Shell command to activate this manager.
 37→    pub activation: String,
 38→}
 39→
 40→/// Result of probing the environment for version managers and tools.
 41→///
 42→/// The probe checks environment variables first, then falls back to default
 43→/// paths. This handles relocatable managers (e.g., `NVM_DIR=/opt/nvm`).
 44→#[derive(Debug, Clone)]
 45→pub struct EnvironmentProbe {
 46→    /// Additional PATH entries discovered from known version manager locations.
 47→    augmented_path: Vec<PathBuf>,
 48→    /// Version managers detected as installed but not active.
 49→    inactive_managers: Vec<InactiveManager>,
 50→}
 51→
 52→/// Definition of a version manager to probe for.
 53→struct ManagerDef {
 54→    name: &'static str,
 55→    env_var: Option<&'static str>,
 56→    default_paths: &'static [&'static str],
 57→    binary_subpath: &'static str,
 58→    path_subpaths: &'static [&'static str],
 59→    activation: &'static str,
 60→}
 61→
 62→/// Known version manager definitions.
 63→const MANAGER_DEFS: &[ManagerDef] = &[
 64→    ManagerDef {
 65→        name: "mise",
 66→        env_var: Some("MISE_DATA_DIR"),
 67→        default_paths: &[".local/share/mise"],
 68→        binary_subpath: "bin/mise",
 69→        path_subpaths: &["bin"],
 70→        activation: "eval \"$(mise activate bash)\"",
 71→    },
 72→    ManagerDef {
 73→        name: "mise-local",
 74→        env_var: None,
 75→        default_paths: &[".local/bin"],
 76→        binary_subpath: "mise",
 77→        path_subpaths: &[],
 78→        activation: "eval \"$(mise activate bash)\"",
 79→    },
 80→    ManagerDef {
 81→        name: "nvm",
 82→        env_var: Some("NVM_DIR"),
 83→        default_paths: &[".nvm"],
 84→        binary_subpath: "nvm.sh",
 85→        path_subpaths: &[],
 86→        activation: "source $NVM_DIR/nvm.sh",
 87→    },
 88→    ManagerDef {
 89→        name: "rbenv",
 90→        env_var: Some("RBENV_ROOT"),
 91→        default_paths: &[".rbenv"],
 92→        binary_subpath: "bin/rbenv",
 93→        path_subpaths: &["bin", "shims"],
 94→        activation: "eval \"$(rbenv init -)\"",
 95→    },
 96→    ManagerDef {
 97→        name: "pyenv",
 98→        env_var: Some("PYENV_ROOT"),
 99→        default_paths: &[".pyenv"],
100→        binary_subpath: "bin/pyenv",
101→        path_subpaths: &["bin", "shims"],
102→        activation: "eval \"$(pyenv init -)\"",
103→    },
104→    ManagerDef {
105→        name: "volta",
106→        env_var: Some("VOLTA_HOME"),
107→        default_paths: &[".volta"],
108→        binary_subpath: "bin/volta",
109→        path_subpaths: &["bin"],
110→        activation: "export PATH=\"$VOLTA_HOME/bin:$PATH\"",
111→    },
112→    ManagerDef {
113→        name: "homebrew",
114→        env_var: Some("HOMEBREW_PREFIX"),
115→        #[cfg(target_arch = "aarch64")]
116→        default_paths: &[],
117→        #[cfg(not(target_arch = "aarch64"))]
118→        default_paths: &[],
119→        binary_subpath: "bin/brew",
120→        path_subpaths: &["bin", "sbin"],
121→        activation: "eval \"$(brew shellenv)\"",
122→    },
123→];
124→
125→/// Check whether a file has executable permission bits set.
126→#[cfg(unix)]
127→pub fn is_executable(path: &Path) -> bool {
128→    use std::os::unix::fs::PermissionsExt;
129→    path.metadata()
130→        .map(|m| m.permissions().mode() & 0o111 != 0)
131→        .unwrap_or(false)
132→}
133→
134→/// On Windows, executability is determined by file extension, not permission bits.
135→#[cfg(not(unix))]
136→pub fn is_executable(_path: &Path) -> bool {
137→    true
138→}
139→
140→/// Resolve a tool's binary path by iterating over PATH entries.
141→///
142→/// Returns the first match that exists and is executable. Does NOT use
143→/// the `which` command — `which` behavior varies across systems and
144→/// is sometimes a shell builtin with inconsistent error handling.
145→pub fn resolve_tool_path(tool: &str, path_entries: &[PathBuf]) -> Option<PathBuf> {
146→    for dir in path_entries {
147→        let candidate = dir.join(tool);
148→        if candidate.is_file() && is_executable(&candidate) {
149→            return Some(candidate);
150→        }
151→    }
152→    None
153→}
154→
155→/// Probe a single manager location, checking env var first then default paths.
156→///
157→/// Returns the install root path if the manager's binary is found.
158→pub fn probe_manager_location<F>(
159→    env_var: Option<&str>,
160→    default_paths: &[PathBuf],
161→    binary_subpath: &str,
162→    env_fn: &F,
163→) -> Option<PathBuf>
164→where
165→    F: Fn(&str) -> Result<String, std::env::VarError>,
166→{
167→    // 1. Check env var first (handles relocatable installs)
168→    if let Some(var) = env_var {
169→        if let Ok(val) = env_fn(var) {
170→            let path = PathBuf::from(val);
171→            if path.join(binary_subpath).exists() {
172→                return Some(path);
173→            }
174→        }
175→    }
176→
177→    // 2. Fall back to default paths
178→    for default in default_paths {
179→        if default.join(binary_subpath).exists() {
180→            return Some(default.clone());
181→        }
182→    }
183→
184→    None
185→}
186→
187→/// Parse the system PATH environment variable into a list of directories.
188→pub fn parse_system_path() -> Vec<PathBuf> {
189→    std::env::var_os("PATH")
190→        .map(|path| std::env::split_paths(&path).collect())
191→        .unwrap_or_default()
192→}
193→
194→impl EnvironmentProbe {
195→    /// Probe the environment using actual environment variables and filesystem.
196→    pub fn run() -> Self {
197→        Self::run_with_env(|key: &str| std::env::var(key))
198→    }
199→
200→    /// Probe the environment with a custom env var lookup function.
201→    ///
202→    /// This allows testing without modifying actual environment variables.
203→    pub fn run_with_env<F>(env_fn: F) -> Self
204→    where
205→        F: Fn(&str) -> Result<String, std::env::VarError>,
206→    {
207→        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/"));
208→        let system_path = parse_system_path();
209→        let mut augmented_path = Vec::new();
210→        let mut inactive_managers = Vec::new();
211→
212→        for def in MANAGER_DEFS {
213→            if let Some(result) = probe_manager(&home, def, &env_fn, &system_path) {
214→                for path in &result.path_additions {
215→                    if !system_path.contains(path) && !augmented_path.contains(path) {
216→                        augmented_path.push(path.clone());
217→                    }
218→                }
219→                if !result.already_on_path {
220→                    inactive_managers.push(InactiveManager {
221→                        name: def.name.to_string(),
222→                        install_path: result.install_path,
223→                        activation: def.activation.to_string(),
224→                    });
225→                }
226→            }
227→        }
228→
229→        // Also check Homebrew at known absolute paths (not relative to home)
230→        for prefix in homebrew_default_prefixes() {
231→            let brew = prefix.join("bin/brew");
232→            if brew.is_file() && is_executable(&brew) {
233→                let bin = prefix.join("bin");
234→                let sbin = prefix.join("sbin");
235→                for dir in [&bin, &sbin] {
236→                    if dir.is_dir() && !system_path.contains(dir) && !augmented_path.contains(dir) {
237→                        augmented_path.push(dir.clone());
238→                    }
239→                }
240→            }
241→        }
242→
243→        Self {
244→            augmented_path,
245→            inactive_managers,
246→        }
247→    }
248→
249→    /// Get the additional PATH entries discovered by the probe.
250→    pub fn augmented_path(&self) -> &[PathBuf] {
251→        &self.augmented_path
252→    }
253→
254→    /// Get the list of inactive version managers.
255→    pub fn inactive_managers(&self) -> &[InactiveManager] {
256→        &self.inactive_managers
257→    }
258→
259→    /// Build a combined PATH: augmented entries prepended to system PATH.
260→    pub fn full_path(&self) -> Vec<PathBuf> {
261→        let system = parse_system_path();
262→        let mut result = self.augmented_path.clone();
263→        result.extend(system);
264→        result
265→    }
266→
267→    /// Re-probe the environment after an install may have changed things.
268→    pub fn refresh(&mut self) {
269→        let refreshed = Self::run();
270→        self.augmented_path = refreshed.augmented_path;
271→        self.inactive_managers = refreshed.inactive_managers;
272→    }
273→}
274→
275→/// Result of probing a single manager.
276→struct ProbeResult {
277→    install_path: PathBuf,
278→    path_additions: Vec<PathBuf>,
279→    already_on_path: bool,
280→}
281→
282→/// Probe a single manager definition.
283→fn probe_manager<F>(
284→    home: &Path,
285→    def: &ManagerDef,
286→    env_fn: &F,
287→    system_path: &[PathBuf],
288→) -> Option<ProbeResult>
289→where
290→    F: Fn(&str) -> Result<String, std::env::VarError>,
291→{
292→    // 1. Check env var first (handles relocatable installs)
293→    let install_path = if let Some(var) = def.env_var {
294→        if let Ok(val) = env_fn(var) {
295→            let path = PathBuf::from(val);
296→            if path.join(def.binary_subpath).exists() {
297→                Some(path)
298→            } else {
299→                None
300→            }
301→        } else {
302→            None
303→        }
304→    } else {
305→        None
306→    };
307→
308→    // 2. Fall back to default paths relative to home
309→    let install_path = install_path.or_else(|| {
310→        for default in def.default_paths {
311→            let path = home.join(default);
312→            if path.join(def.binary_subpath).exists() {
313→                return Some(path);
314→            }
315→        }
316→        None
317→    })?;
318→
319→    // 3. Compute path additions
320→    let path_additions: Vec<PathBuf> = def
321→        .path_subpaths
322→        .iter()
323→        .map(|sub| install_path.join(sub))
324→        .filter(|p| p.is_dir())
325→        .collect();
326→
327→    // 4. Check if already on system PATH
328→    let already_on_path = path_additions.iter().all(|p| system_path.contains(p));
329→
330→    Some(ProbeResult {
331→        install_path,
332→        path_additions,
333→        already_on_path,
334→    })
335→}
336→
337→/// Default Homebrew prefix paths to check (absolute, not relative to home).
338→fn homebrew_default_prefixes() -> Vec<PathBuf> {
339→    let mut prefixes = Vec::new();
340→    if cfg!(target_os = "macos") {
341→        if cfg!(target_arch = "aarch64") {
342→            prefixes.push(PathBuf::from("/opt/homebrew"));
343→        } else {
344→            prefixes.push(PathBuf::from("/usr/local"));
345→        }
346→    } else if cfg!(target_os = "linux") {
347→        prefixes.push(PathBuf::from("/home/linuxbrew/.linuxbrew"));
348→    }
349→    prefixes
350→}
