//! Git template fetching.
//!
//! Provides functionality for cloning and updating git repositories
//! to fetch templates, with support for specific refs and update detection.

use anyhow::{bail, Result};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};

/// Fetches templates from git repositories.
pub struct GitFetcher {
    /// Directory for cloned repositories.
    clone_dir: PathBuf,
}

/// Information about a git fetch.
#[derive(Debug)]
pub struct GitFetchResult {
    /// Path to the fetched content.
    pub local_path: PathBuf,
    /// Current commit SHA.
    pub commit_sha: String,
}

impl GitFetcher {
    /// Create a new git fetcher.
    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
        Self {
            clone_dir: clone_dir.into(),
        }
    }

    /// Get the clone directory.
    pub fn clone_dir(&self) -> &PathBuf {
        &self.clone_dir
    }

    /// Clone or update a repository.
    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
        let repo_path = self.repo_path(url);

        if repo_path.exists() {
            self.update_repo(&repo_path, git_ref)?;
        } else {
            self.clone_repo(url, &repo_path, git_ref)?;
        }

        let commit_sha = self.get_head_sha(&repo_path)?;

        Ok(GitFetchResult {
            local_path: repo_path,
            commit_sha,
        })
    }

    /// Check if a repository has new commits.
    pub fn has_updates(&self, url: &str, git_ref: Option<&str>, current_sha: &str) -> Result<bool> {
        let remote_sha = self.resolve_ref(url, git_ref)?;
        Ok(remote_sha != current_sha)
    }

    /// Get the current commit SHA for a ref using ls-remote.
    pub fn resolve_ref(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
        let refspec = git_ref.unwrap_or("HEAD");

        // Try the refspec directly, then with refs/heads/ and refs/tags/ prefixes.
        // Short refspecs like "v1.0" may not match "refs/tags/v1.0" in all git versions.
        let candidates = if refspec == "HEAD" {
            vec![refspec.to_string()]
        } else {
            vec![
                refspec.to_string(),
                format!("refs/heads/{refspec}"),
                format!("refs/tags/{refspec}"),
            ]
        };

        for candidate in &candidates {
            let output = std::process::Command::new("git")
                .args(["ls-remote", url, candidate])
                .output()?;

            if !output.status.success() {
                bail!(
                    "Failed to query remote: {}",
                    String::from_utf8_lossy(&output.stderr)
                );
            }

            let stdout = String::from_utf8_lossy(&output.stdout);
            if let Some(sha) = stdout
                .lines()
                .next()
                .and_then(|line| line.split_whitespace().next())
            {
                return Ok(sha.to_string());
            }
        }

        bail!("Could not resolve ref '{refspec}' from {url}")
    }

    fn clone_repo(&self, url: &str, path: &Path, git_ref: Option<&str>) -> Result<()> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }

        let mut cmd = std::process::Command::new("git");
        cmd.args(["clone", "--depth", "1"]);

        if let Some(r) = git_ref {
            cmd.args(["--branch", r]);
        }

        cmd.args([url, &path.to_string_lossy()]);

        let output = cmd.output()?;
        if !output.status.success() {
            bail!(
                "Git clone failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }

        Ok(())
    }

    fn update_repo(&self, path: &PathBuf, git_ref: Option<&str>) -> Result<()> {
        let output = std::process::Command::new("git")
            .args(["fetch", "origin"])
            .current_dir(path)
            .output()?;

        if !output.status.success() {
            bail!(
                "Git fetch failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }

        let refspec = if let Some(r) = git_ref {
            format!("origin/{}", r)
        } else {
            "origin/HEAD".to_string()
        };

        let output = std::process::Command::new("git")
            .args(["reset", "--hard", &refspec])
            .current_dir(path)
            .output()?;

        if !output.status.success() {
            bail!(
                "Git reset failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }

        Ok(())
    }

    fn get_head_sha(&self, path: &PathBuf) -> Result<String> {
        let output = std::process::Command::new("git")
            .args(["rev-parse", "HEAD"])
            .current_dir(path)
            .output()?;

        if !output.status.success() {
            bail!("Git rev-parse failed");
        }

        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
    }

    /// Get the local path for a repository.
    ///
    /// Uses a hash of the URL to create a deterministic, unique path.
    pub fn repo_path(&self, url: &str) -> PathBuf {
        let hash = Sha256::digest(url.as_bytes());
        let hash_str = hex::encode(&hash[..8]);
        self.clone_dir.join(hash_str)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Mutex;
    use tempfile::TempDir;

    // Serialize git-process tests to avoid flaky failures under parallel execution
    static GIT_LOCK: Mutex<()> = Mutex::new(());

    #[test]
    fn creates_fetcher_with_clone_dir() {
        let temp = TempDir::new().unwrap();
        let fetcher = GitFetcher::new(temp.path());

        assert_eq!(fetcher.clone_dir(), temp.path());
    }

    #[test]
    fn git_fetch_result_fields() {
        let result = GitFetchResult {
            local_path: PathBuf::from("/tmp/repo"),
            commit_sha: "abc123def456".to_string(),
        };

        assert_eq!(result.local_path, PathBuf::from("/tmp/repo"));
        assert_eq!(result.commit_sha, "abc123def456");
    }

    #[test]
    fn repo_path_is_deterministic() {
        let temp = TempDir::new().unwrap();
        let fetcher = GitFetcher::new(temp.path());

        let path1 = fetcher.repo_path("https://github.com/org/repo.git");
        let path2 = fetcher.repo_path("https://github.com/org/repo.git");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_repos_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let fetcher = GitFetcher::new(temp.path());

        let path1 = fetcher.repo_path("https://github.com/org/repo1.git");
        let path2 = fetcher.repo_path("https://github.com/org/repo2.git");

        assert_ne!(path1, path2);
    }

    #[test]
    fn repo_path_is_within_clone_dir() {
        let temp = TempDir::new().unwrap();
        let fetcher = GitFetcher::new(temp.path());

        let path = fetcher.repo_path("https://github.com/org/repo.git");

        assert!(path.starts_with(temp.path()));
    }

    #[test]
    fn repo_path_uses_hex_hash() {
        let temp = TempDir::new().unwrap();
        let fetcher = GitFetcher::new(temp.path());

        let path = fetcher.repo_path("https://github.com/org/repo.git");
        let filename = path.file_name().unwrap().to_string_lossy();

        // Should be 16 hex characters (8 bytes encoded)
        assert_eq!(filename.len(), 16);
        assert!(filename.chars().all(|c| c.is_ascii_hexdigit()));
    }

    // --- Local bare repo git tests ---

    /// Create a bare git repo with an initial commit containing a template file.
    /// Returns the path to the bare repo.
    fn create_bare_repo(parent: &Path) -> PathBuf {
        let bare_path = parent.join("test-repo.git");

        // Create a temporary working directory for the initial commit
        let work_dir = parent.join("work");
        std::fs::create_dir_all(&work_dir).unwrap();

        // Initialize bare repo with explicit default branch
        let output = std::process::Command::new("git")
            .args([
                "init",
                "--bare",
                "--initial-branch=main",
                bare_path.to_string_lossy().as_ref(),
            ])
            .output()
            .unwrap();
        assert!(output.status.success(), "bare init failed");

        // Clone bare to working dir
        let output = std::process::Command::new("git")
            .args([
                "clone",
                bare_path.to_string_lossy().as_ref(),
                work_dir.to_string_lossy().as_ref(),
            ])
            .output()
            .unwrap();
        assert!(output.status.success(), "clone failed");

        // Configure git user for commits
        for (key, val) in [("user.name", "Test"), ("user.email", "test@test.com")] {
            let output = std::process::Command::new("git")
                .args(["config", key, val])
                .current_dir(&work_dir)
                .output()
                .unwrap();
            assert!(output.status.success(), "git config {key} failed");
        }

        // Create a template file and commit
        let templates_dir = work_dir.join("templates");
        std::fs::create_dir_all(&templates_dir).unwrap();
        std::fs::write(
            templates_dir.join("node.yml"),
            "name: node\ncommand: npm install\n",
        )
        .unwrap();

        let output = std::process::Command::new("git")
            .args(["add", "."])
            .current_dir(&work_dir)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git add failed in create_bare_repo"
        );

        let output = std::process::Command::new("git")
            .args(["commit", "-m", "Initial commit"])
            .current_dir(&work_dir)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git commit failed in create_bare_repo: {}",
            String::from_utf8_lossy(&output.stderr)
        );

        let output = std::process::Command::new("git")
            .args(["push", "origin", "HEAD:main"])
            .current_dir(&work_dir)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git push failed in create_bare_repo: {}",
            String::from_utf8_lossy(&output.stderr)
        );

        bare_path
    }

    /// Push a new commit to the bare repo.
    fn push_commit_to_bare(parent: &Path, bare_path: &Path) {
        let work_dir = parent.join("work2");

        let output = std::process::Command::new("git")
            .args([
                "clone",
                &bare_path.to_string_lossy(),
                &work_dir.to_string_lossy(),
            ])
            .output()
            .unwrap();
        assert!(output.status.success(), "clone for push failed");

        for (key, val) in [("user.name", "Test"), ("user.email", "test@test.com")] {
            std::process::Command::new("git")
                .args(["config", key, val])
                .current_dir(&work_dir)
                .output()
                .unwrap();
        }

        std::fs::write(work_dir.join("new-file.txt"), "new content").unwrap();

        let output = std::process::Command::new("git")
            .args(["add", "."])
            .current_dir(&work_dir)
            .output()
            .unwrap();
        assert!(output.status.success(), "git add failed");

        let output = std::process::Command::new("git")
            .args(["commit", "-m", "Second commit"])
            .current_dir(&work_dir)
            .output()
            .unwrap();
        assert!(output.status.success(), "git commit failed");

        let output = std::process::Command::new("git")
            .args(["push", "origin", "HEAD:main"])
            .current_dir(&work_dir)
            .output()
            .unwrap();
        assert!(output.status.success(), "git push failed");
    }

    #[test]
    fn clone_from_local_bare_repo() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();
        let bare_path = create_bare_repo(temp.path());

        let clone_dir = temp.path().join("clones");
        let fetcher = GitFetcher::new(&clone_dir);

        let result = fetcher
            .fetch(&bare_path.to_string_lossy(), Some("main"))
            .unwrap();

        assert!(!result.commit_sha.is_empty());
        assert!(result.local_path.exists());
        // Template file should exist in clone
        assert!(result.local_path.join("templates/node.yml").exists());
    }

    #[test]
    fn has_updates_false_when_no_new_commits() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();
        let bare_path = create_bare_repo(temp.path());

        let clone_dir = temp.path().join("clones");
        let fetcher = GitFetcher::new(&clone_dir);

        // Clone first
        let result = fetcher
            .fetch(&bare_path.to_string_lossy(), Some("main"))
            .unwrap();

        // No changes have been made
        let has_updates = fetcher
            .has_updates(
                &bare_path.to_string_lossy(),
                Some("main"),
                &result.commit_sha,
            )
            .unwrap();

        assert!(!has_updates);
    }

    #[test]
    fn has_updates_true_after_push() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();
        let bare_path = create_bare_repo(temp.path());

        let clone_dir = temp.path().join("clones");
        let fetcher = GitFetcher::new(&clone_dir);

        // Clone and get initial SHA
        let result = fetcher
            .fetch(&bare_path.to_string_lossy(), Some("main"))
            .unwrap();
        let initial_sha = result.commit_sha;

        // Push a new commit
        push_commit_to_bare(temp.path(), &bare_path);

        // Now should detect updates
        let has_updates = fetcher
            .has_updates(&bare_path.to_string_lossy(), Some("main"), &initial_sha)
            .unwrap();

        assert!(has_updates);
    }

    #[test]
    fn ref_resolution_branch() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();
        let bare_path = create_bare_repo(temp.path());

        let fetcher = GitFetcher::new(temp.path().join("clones"));

        let sha = fetcher
            .resolve_ref(&bare_path.to_string_lossy(), Some("main"))
            .unwrap();

        assert!(!sha.is_empty());
        // SHA should be 40 hex characters
        assert_eq!(sha.len(), 40);
        assert!(sha.chars().all(|c| c.is_ascii_hexdigit()));
    }

    #[test]
    fn ref_resolution_tag() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();
        let bare_path = create_bare_repo(temp.path());

        // Create a tag
        let work_dir = temp.path().join("tag-work");
        std::process::Command::new("git")
            .args([
                "clone",
                &bare_path.to_string_lossy(),
                &work_dir.to_string_lossy(),
            ])
            .output()
            .unwrap();

        for (key, val) in [("user.name", "Test"), ("user.email", "test@test.com")] {
            std::process::Command::new("git")
                .args(["config", key, val])
                .current_dir(&work_dir)
                .output()
                .unwrap();
        }

        let output = std::process::Command::new("git")
            .args(["tag", "v1.0"])
            .current_dir(&work_dir)
            .output()
            .unwrap();
        assert!(output.status.success(), "tag creation failed");

        let output = std::process::Command::new("git")
            .args(["push", "origin", "v1.0"])
            .current_dir(&work_dir)
            .output()
            .unwrap();
        assert!(output.status.success(), "tag push failed");

        let fetcher = GitFetcher::new(temp.path().join("clones"));

        let sha = fetcher
            .resolve_ref(&bare_path.to_string_lossy(), Some("v1.0"))
            .unwrap();

        assert!(!sha.is_empty());
        assert_eq!(sha.len(), 40);
    }

    #[test]
    fn invalid_repo_url_returns_error() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();
        let fetcher = GitFetcher::new(temp.path().join("clones"));

        let result = fetcher.fetch("/nonexistent/path/repo.git", Some("main"));

        assert!(result.is_err());
    }

    #[test]
    fn fetch_specific_subdirectory() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();
        let bare_path = create_bare_repo(temp.path());

        let clone_dir = temp.path().join("clones");
        let fetcher = GitFetcher::new(&clone_dir);

        let result = fetcher
            .fetch(&bare_path.to_string_lossy(), Some("main"))
            .unwrap();

        // The "templates" subdirectory should contain our template
        let templates_path = result.local_path.join("templates");
        assert!(templates_path.is_dir());

        let content = std::fs::read_to_string(templates_path.join("node.yml")).unwrap();
        assert!(content.contains("npm install"));
    }
}

//! Gap checker for requirement evaluation.
//!
//! The `GapChecker` evaluates whether system-level requirements are met,
//! caching results within a run to avoid redundant command executions.

use crate::requirements::probe::EnvironmentProbe;
use crate::requirements::registry::{
    InstallContext, Platform, RequirementCheck, RequirementRegistry,
};
use crate::requirements::status::{GapResult, RequirementStatus};
use crate::steps::resolved::ResolvedStep;
use std::collections::{HashMap, HashSet};
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Duration;

/// Checks whether requirements are satisfied on the system.
///
/// Caches results per-run so the same requirement checked multiple times
/// only executes commands once.
pub struct GapChecker<'a> {
    registry: &'a RequirementRegistry,
    probe: &'a EnvironmentProbe,
    project_root: PathBuf,
    pub(crate) cache: HashMap<String, RequirementStatus>,
}

impl<'a> GapChecker<'a> {
    /// Create a new gap checker.
    pub fn new(
        registry: &'a RequirementRegistry,
        probe: &'a EnvironmentProbe,
        project_root: &Path,
    ) -> Self {
        Self {
            registry,
            probe,
            project_root: project_root.to_path_buf(),
            cache: HashMap::new(),
        }
    }

    /// Check all requirements for a step, returning only non-satisfied gaps.
    ///
    /// `provided_requirements` is authoritative — if the environment says
    /// a requirement is provided, skip the check regardless of what the
    /// step's requires list says. Until environments exist, callers pass `None`.
    pub fn check_step(
        &mut self,
        step: &ResolvedStep,
        provided: Option<&HashSet<String>>,
    ) -> Vec<GapResult> {
        let mut gaps = Vec::new();
        for req_name in &step.requires {
            if let Some(provided_set) = provided {
                if provided_set.contains(req_name) {
                    continue;
                }
            }

            let status = self.check_one(req_name);
            if !status.is_satisfied() {
                gaps.push(GapResult {
                    requirement: req_name.clone(),
                    status,
                });
            }
        }
        gaps
    }

    /// Check a single requirement, using cache when available.
    pub fn check_one(&mut self, requirement: &str) -> RequirementStatus {
        if let Some(cached) = self.cache.get(requirement) {
            return cached.clone();
        }

        let status = self.evaluate(requirement);
        self.cache.insert(requirement.to_string(), status.clone());
        status
    }

    /// Invalidate a cached result for a specific requirement.
    pub fn invalidate(&mut self, requirement: &str) {
        self.cache.remove(requirement);
    }

    /// Invalidate all cached results.
    pub fn invalidate_all(&mut self) {
        self.cache.clear();
    }

    /// Resolve the install dependency chain for a requirement.
    ///
    /// Returns the ordered list of requirements that need to be installed,
    /// with dependencies before dependents. Max depth 5, detects circular deps.
    pub fn resolve_install_deps(&self, requirement: &str) -> Result<Vec<String>, String> {
        let mut chain = Vec::new();
        let mut visited = HashSet::new();
        self.resolve_deps_recursive(requirement, &mut chain, &mut visited, 0)?;
        Ok(chain)
    }

    fn resolve_deps_recursive(
        &self,
        requirement: &str,
        chain: &mut Vec<String>,
        visited: &mut HashSet<String>,
        depth: usize,
    ) -> Result<(), String> {
        const MAX_DEPTH: usize = 5;

        if depth > MAX_DEPTH {
            return Err(format!(
                "Requirement dependency chain exceeds max depth of {} for '{}'",
                MAX_DEPTH, requirement
            ));
        }

        if visited.contains(requirement) {
            return Err(format!(
                "Circular dependency detected: '{}' appears twice in the chain",
                requirement
            ));
        }

        let Some(req) = self.registry.get(requirement) else {
            // Unknown requirement — add it to chain, let caller handle
            if !chain.contains(&requirement.to_string()) {
                chain.push(requirement.to_string());
            }
            return Ok(());
        };

        visited.insert(requirement.to_string());

        // Resolve static dependencies
        for dep in &req.depends_on {
            self.resolve_deps_recursive(dep, chain, visited, depth + 1)?;
        }

        // Resolve dynamic dependencies
        if let Some(install_requires_fn) = req.install_requires {
            let ctx = self.build_install_context();
            let dynamic_deps = install_requires_fn(&ctx);
            for dep in &dynamic_deps {
                if !visited.contains(dep) {
                    self.resolve_deps_recursive(dep, chain, visited, depth + 1)?;
                }
            }
        }

        // Add this requirement after its dependencies
        if !chain.contains(&requirement.to_string()) {
            chain.push(requirement.to_string());
        }

        visited.remove(requirement);
        Ok(())
    }

    fn build_install_context(&self) -> InstallContext {
        let detected_managers = self
            .probe
            .inactive_managers()
            .iter()
            .map(|m| m.name.clone())
            .collect::<Vec<_>>();
        InstallContext {
            detected_managers,
            platform: Platform::current(),
        }
    }

    /// Check whether the network is reachable.
    ///
    /// Attempts a TCP connection to a well-known host with a 2-second timeout.
    /// Returns `true` if the connection succeeds, `false` otherwise.
    pub fn check_network(&self) -> bool {
        // Try multiple well-known hosts to reduce false negatives
        const TARGETS: &[(&str, u16)] = &[
            ("1.1.1.1", 443), // Cloudflare DNS
            ("8.8.8.8", 443), // Google DNS
            ("9.9.9.9", 443), // Quad9 DNS
        ];
        let timeout = Duration::from_secs(2);

        for &(host, port) in TARGETS {
            let addr = format!("{}:{}", host, port);
            if let Ok(addr) = addr.parse() {
                if TcpStream::connect_timeout(&addr, timeout).is_ok() {
                    return true;
                }
            }
        }
        false
    }

    fn evaluate(&self, requirement: &str) -> RequirementStatus {
        let Some(req) = self.registry.get(requirement) else {
            return RequirementStatus::Unknown;
        };

        for check in &req.checks {
            if let Some(status) = self.evaluate_check(check, req) {
                return status;
            }
        }

        // No check matched — Missing
        RequirementStatus::Missing {
            install_template: req.install_template.clone(),
            install_hint: req.install_hint.clone(),
        }
    }

    fn evaluate_check(
        &self,
        check: &RequirementCheck,
        req: &crate::requirements::registry::Requirement,
    ) -> Option<RequirementStatus> {
        match check {
            RequirementCheck::CommandSucceeds(cmd) => {
                if self.run_command_succeeds(cmd) {
                    Some(RequirementStatus::Satisfied)
                } else {
                    None
                }
            }
            RequirementCheck::FileExists(path) => {
                let full_path = if Path::new(path).is_absolute() {
                    PathBuf::from(path)
                } else {
                    self.project_root.join(path)
                };
                if full_path.exists() {
                    Some(RequirementStatus::Satisfied)
                } else {
                    None
                }
            }
            RequirementCheck::ServiceReachable(cmd) => {
                if self.run_command_succeeds(cmd) {
                    Some(RequirementStatus::Satisfied)
                } else {
                    // Service check is the main/only check — return ServiceDown
                    Some(RequirementStatus::ServiceDown {
                        binary_present: self.check_binary_present(cmd),
                        install_template: req.install_template.clone(),
                        start_command: None,
                        start_hint: req
                            .install_hint
                            .clone()
                            .unwrap_or_else(|| format!("Start the {} service", req.name)),
                    })
                }
            }
            RequirementCheck::ManagedCommand {
                command: tool,
                managed_path_patterns,
                system_path_patterns,
                version_file,
            } => self.evaluate_managed_command(
                tool,
                managed_path_patterns,
                system_path_patterns,
                version_file.as_deref(),
                req,
            ),
            RequirementCheck::Any(sub_checks) => {
                for sub in sub_checks {
                    if let Some(status) = self.evaluate_check(sub, req) {
                        if status.is_satisfied() || status.can_proceed() {
                            return Some(status);
                        }
                    }
                }
                None
            }
        }
    }

    fn evaluate_managed_command(
        &self,
        tool: &str,
        managed_path_patterns: &[String],
        system_path_patterns: &[String],
        version_file: Option<&str>,
        req: &crate::requirements::registry::Requirement,
    ) -> Option<RequirementStatus> {
        let full_path = self.probe.full_path();

        // Resolve where the tool is on the full (augmented) PATH
        if let Some(resolved) =
            crate::requirements::probe::resolve_tool_path(tool, full_path.as_slice())
        {
            let path_str = resolved.to_string_lossy().to_string();

            // Check 1: Managed path patterns -> Satisfied
            for pattern in managed_path_patterns {
                if path_str.contains(pattern) {
                    return Some(RequirementStatus::Satisfied);
                }
            }

            // Check 2: Inactive manager with version file
            if let Some(vf) = version_file {
                if self.project_root.join(vf).exists()
                    || self.project_root.join(".tool-versions").exists()
                {
                    // Check if the tool was found via augmented path (not original PATH)
                    let original_path = crate::requirements::probe::parse_system_path();
                    let on_original =
                        crate::requirements::probe::resolve_tool_path(tool, &original_path);
                    if on_original.is_none() {
                        // Tool is only on augmented path — it's from an inactive manager
                        for mgr in self.probe.inactive_managers() {
                            let mgr_binary = format!("{}/", mgr.name);
                            if path_str.contains(&mgr_binary)
                                || resolved.starts_with(&mgr.install_path)
                            {
                                return Some(RequirementStatus::Inactive {
                                    manager: mgr.name.clone(),
                                    binary_path: resolved,
                                    activation_hint: mgr.activation.clone(),
                                });
                            }
                        }
                    }
                }
            }

            // Check 3: System path patterns -> SystemOnly
            for pattern in system_path_patterns {
                if path_str.contains(pattern) || path_str.starts_with(pattern) {
                    return Some(RequirementStatus::SystemOnly {
                        path: resolved,
                        install_template: req.install_template.clone(),
                        warning: format!(
                            "System {} detected at {}. Consider using a version manager.",
                            tool, path_str
                        ),
                    });
                }
            }

            // Check 4: Found on PATH, none of the above -> Satisfied
            return Some(RequirementStatus::Satisfied);
        }

        // Check 5: Nothing found -> None (let caller handle as Missing)
        None
    }

    fn run_command_succeeds(&self, cmd: &str) -> bool {
        let full_path_str = self
            .probe
            .full_path()
            .iter()
            .map(|p| p.to_string_lossy().to_string())
            .collect::<Vec<_>>()
            .join(":");

        Command::new("sh")
            .arg("-c")
            .arg(cmd)
            .env("PATH", &full_path_str)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .is_ok_and(|s| s.success())
    }

    fn check_binary_present(&self, service_cmd: &str) -> bool {
        // Extract the first word of the command as the binary name
        let binary = service_cmd.split_whitespace().next().unwrap_or("");
        if binary.is_empty() {
            return false;
        }
        let full_path = self.probe.full_path();
        crate::requirements::probe::resolve_tool_path(binary, full_path.as_slice()).is_some()
    }
}

