                install_template: None,
                install_hint: None,
                depends_on: vec!["tool_b".to_string()],
                install_requires: None,
            },
        );
        registry.insert(
            "tool_b".to_string(),
            Requirement {
                name: "tool_b".to_string(),
                checks: vec![RequirementCheck::CommandSucceeds("false".to_string())],
                install_template: None,
