  1→//! Cache storage implementation.
  2→
  3→use sha2::{Digest, Sha256};
  4→use std::fs;
  5→use std::path::{Path, PathBuf};
  6→
  7→use super::entry::CacheEntry;
  8→use crate::error::{BivvyError, Result};
  9→
 10→/// Storage for cached templates.
 11→pub struct CacheStore {
 12→    /// Root directory for cache.
 13→    root: PathBuf,
 14→}
 15→
 16→impl CacheStore {
 17→    /// Create a new cache store.
 18→    pub fn new(root: impl Into<PathBuf>) -> Self {
 19→        Self { root: root.into() }
 20→    }
 21→
 22→    /// Get the cache root directory.
 23→    pub fn root(&self) -> &Path {
 24→        &self.root
 25→    }
 26→
 27→    /// Ensure the cache directory exists.
 28→    fn ensure_dir(&self) -> Result<()> {
 29→        fs::create_dir_all(&self.root).map_err(|e| BivvyError::CacheError {
 30→            message: format!("Failed to create cache directory {:?}: {}", self.root, e),
 31→        })
 32→    }
 33→
 34→    /// Get the path for storing an entry's content.
 35→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 36→        let key = format!("{}:{}", source_id, template_name);
 37→        let hash = Sha256::digest(key.as_bytes());
 38→        let hash_str = hex::encode(&hash[..16]);
 39→        self.root.join(hash_str)
 40→    }
 41→
 42→    /// Get the metadata file path for an entry.
 43→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 44→        self.content_path(source_id, template_name)
 45→            .with_extension("meta.json")
 46→    }
 47→
 48→    /// Store content and return a cache entry.
 49→    pub fn store(
 50→        &self,
 51→        source_id: &str,
 52→        template_name: &str,
 53→        content: &str,
 54→        ttl_seconds: u64,
 55→    ) -> Result<CacheEntry> {
 56→        self.ensure_dir()?;
 57→
 58→        let content_path = self.content_path(source_id, template_name);
 59→        fs::write(&content_path, content)?;
 60→
 61→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 62→            .with_size(content.len() as u64);
 63→
 64→        self.save_metadata(&entry)?;
 65→
 66→        Ok(entry)
 67→    }
 68→
 69→    /// Load a cached entry's metadata.
 70→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 71→        let meta_path = self.metadata_path(source_id, template_name);
 72→
 73→        if !meta_path.exists() {
 74→            return Ok(None);
 75→        }
 76→
 77→        let json = fs::read_to_string(&meta_path)?;
 78→        let entry: CacheEntry =
 79→            serde_json::from_str(&json).map_err(|e| BivvyError::CacheError {
 80→                message: format!("Failed to parse cache metadata {:?}: {}", meta_path, e),
 81→            })?;
 82→
 83→        Ok(Some(entry))
 84→    }
 85→
 86→    /// Read the cached content.
 87→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
 88→        fs::read_to_string(&entry.content_path).map_err(|e| BivvyError::CacheError {
 89→            message: format!(
 90→                "Failed to read cached content from {:?}: {}",
 91→                entry.content_path, e
 92→            ),
 93→        })
 94→    }
 95→
 96→    /// Save entry metadata.
 97→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
 98→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
 99→        let json =
100→            serde_json::to_string_pretty(entry).map_err(|e| BivvyError::CacheError {
101→                message: format!("Failed to serialize cache metadata: {}", e),
102→            })?;
103→        fs::write(&meta_path, json)?;
104→        Ok(())
105→    }
106→
107→    /// Update an entry's metadata (e.g., after revalidation).
108→    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
109→        self.save_metadata(entry)
110→    }
111→
112→    /// Remove a cached entry.
113→    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
114→        let content_path = self.content_path(source_id, template_name);
115→        let meta_path = self.metadata_path(source_id, template_name);
116→
117→        let mut removed = false;
118→
119→        if content_path.exists() {
120→            fs::remove_file(&content_path)?;
121→            removed = true;
122→        }
123→
124→        if meta_path.exists() {
125→            fs::remove_file(&meta_path)?;
126→            removed = true;
127→        }
128→
129→        Ok(removed)
130→    }
131→
132→    /// List all cached entries.
133→    pub fn list(&self) -> Result<Vec<CacheEntry>> {
134→        self.ensure_dir()?;
135→
136→        let mut entries = Vec::new();
137→
138→        for entry in fs::read_dir(&self.root)? {
139→            let entry = entry?;
140→            let path = entry.path();
141→
142→            if path.extension().is_some_and(|e| e == "json") {
143→                if let Ok(json) = fs::read_to_string(&path) {
144→                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
145→                        entries.push(cache_entry);
146→                    }
147→                }
148→            }
149→        }
150→
151→        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
152→        Ok(entries)
153→    }
154→
155→    /// Clear all cached entries.
156→    pub fn clear(&self) -> Result<usize> {
157→        let entries = self.list()?;
158→        let count = entries.len();
159→
160→        for entry in entries {
161→            let _ = self.remove(&entry.source_id, &entry.template_name);
162→        }
163→
164→        Ok(count)
165→    }
166→
167→    /// Get total cache size in bytes.
168→    pub fn total_size(&self) -> Result<u64> {
169→        let entries = self.list()?;
170→        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
171→    }
172→}
173→
