182→        let store = CacheStore::new(temp.path());
183→
184→        assert_eq!(store.root(), temp.path());
185→    }
186→
187→    #[test]
188→    fn store_and_load() {
189→        let temp = TempDir::new().unwrap();
190→        let store = CacheStore::new(temp.path());
